# This file imports the full FastAPI app/route graph. Keep it in the serial
# regression lane so xdist cannot multiply the route-model memory footprint.
pytestmark = pytest.mark.serial

_ACTIVE_TEST_CLIENTS: list[TestClient] = []
_ACTIVE_TEST_STORE_DIRS: list[Path] = []


def _tracked_test_client(app) -> TestClient:
    client = TestClient(app)
    _ACTIVE_TEST_CLIENTS.append(client)
    return client


@pytest.fixture(autouse=True)
def _close_admin_api_test_clients_after_each_test():
    yield
    while _ACTIVE_TEST_CLIENTS:
        client = _ACTIVE_TEST_CLIENTS.pop()
        try:
            client.app.dependency_overrides.clear()
        finally:
            client.close()
    gc.collect()
    while _ACTIVE_TEST_STORE_DIRS:
        shutil.rmtree(_ACTIVE_TEST_STORE_DIRS.pop(), ignore_errors=True)


def _headers(
    *,
    idempotency_key: str = "idem-001",
    operator_intent: str = "manual_one_off",
    roles: str = AdminApiRole.TRADER.value,
) -> dict[str, str]:
    return {
        "Authorization": "Bearer test-admin-token",
        "Idempotency-Key": idempotency_key,
        "X-Correlation-Id": "corr-001",
        "X-Operator-Intent": operator_intent,
        "X-Admin-Actor": "operator-001",
        "X-Admin-Roles": roles,
    }


def _store_dir() -> Path:
    path = Path(tempfile.mkdtemp(prefix="coinbase-admin-api-contract-"))
    _ACTIVE_TEST_STORE_DIRS.append(path)
    return path


@pytest.mark.regression
def test_admin_api_contract_store_dir_is_disposable_and_outside_runtime_state():
    store_dir = _store_dir()

    assert store_dir.name.startswith("coinbase-admin-api-contract-")
    assert not store_dir.is_relative_to(ROOT / "runtime_state")
    assert not store_dir.is_relative_to(ROOT / "genai_tools")


class _FakeUsdcPairSnapshotLiveOrderExecutor:
    def __init__(self) -> None:
        self.calls: list[dict] = []

    def submit_and_cancel(self, **kwargs):
        self.calls.append(dict(kwargs))
        client_order_id = kwargs["client_order_id"]
        order_configuration = kwargs["order_configuration"]
        return {
            "coinbase_order_id": "exchange-m58-live-submit-1",
            "submit_result": {
                "success": True,
                "order_id": "exchange-m58-live-submit-1",
                "client_order_id": client_order_id,
            },
            "cancel_result": {
                "success": True,
                "client_order_id": client_order_id,
            },
            "submitted_at": "2026-07-06T14:20:00+00:00",
            "cancelled_at": "2026-07-06T14:20:01+00:00",
            "order_configuration": order_configuration,
            "live_exchange_submitted": True,
            "live_coinbase_orders_ran": True,
            "live_coinbase_execution": "submitted_cancelled",
            "executed_notional_usdc": "0",
        }


