def _assert_stealth_command_execution_contract(
    payload: dict,
    *,
    mutation_family: str,
    route: str,
    service_method: str,
    identity_value: str,
    required_prerequisites: set[str],
    command_specific_prerequisite: str,
    module_id: str = "stealth_orders",
    resolved_prerequisites: set[str] | None = None,
) -> None:
    contract = payload["stealth_command_execution_contract"]
    resolved_prerequisites = resolved_prerequisites or set()
    missing_prerequisites = required_prerequisites - resolved_prerequisites
    assert contract["mutation_family"] == mutation_family
    assert contract["command_route"] == route
    assert contract["service_method"] == service_method
    assert contract["identity_key"] == "stealth_order_id"
    assert contract["stealth_order_id"] == identity_value
    assert contract["status"] == AdminApiGateStatus.BLOCKED.value
    assert contract["execution_contract_boundary_configured"] is True
    assert contract["execution_contract_available"] is False
    assert contract["execution_allowed"] is False
    assert contract["exact_command_context_present"] is True
    assert set(contract["required_context_fields"]) == {
        field.value for field in AdminApiStealthAdmissionContextField
    }
    assert contract["missing_context_fields"] == []
    assert set(contract["required_prerequisites"]) == required_prerequisites
    assert set(contract["missing_prerequisites"]) == missing_prerequisites
    assert set(contract["resolved_prerequisites"]) == resolved_prerequisites
    assert contract["prerequisite_resolver_available"] is True
    assert contract["prerequisite_resolver_lookup_ran"] is True
    assert contract["prerequisite_resolver_authority"] == "read_only_no_execution"
    assert StealthCommandExecutionBlocker.EXECUTION_CONTRACT_MISSING.value in (
        contract["blockers"]
    )
    if (
        StealthCommandExecutionPrerequisite.LIVE_EXECUTION_SERVICE.value
        in resolved_prerequisites
    ):
        assert (
            StealthCommandExecutionBlocker.LIVE_EXECUTION_DISABLED.value
            not in contract["blockers"]
        )
    else:
        assert StealthCommandExecutionBlocker.LIVE_EXECUTION_DISABLED.value in (
            contract["blockers"]
        )
    if (
        StealthCommandExecutionPrerequisite.LIVE_EXECUTION_ADAPTER.value
        in resolved_prerequisites
    ):
        assert (
            StealthCommandExecutionBlocker.LIVE_EXECUTION_ADAPTER_DISABLED.value
            not in contract["blockers"]
        )
    else:
        assert (
            StealthCommandExecutionBlocker.LIVE_EXECUTION_ADAPTER_DISABLED.value
            in contract["blockers"]
        )
    assert f"{command_specific_prerequisite}_missing" in contract["blockers"]
    _assert_remaining_execution_blocker_chain(
        contract,
        create=False,
        post_write_resolved=False,
        service_resolved=(
            StealthCommandExecutionPrerequisite.LIVE_EXECUTION_SERVICE.value
            in resolved_prerequisites
        ),
        adapter_resolved=(
            StealthCommandExecutionPrerequisite.LIVE_EXECUTION_ADAPTER.value
            in resolved_prerequisites
        ),
    )
    resolution_by_prerequisite = {
        row["prerequisite"]: row
        for row in contract["prerequisite_resolution"]
    }
    assert set(resolution_by_prerequisite) == required_prerequisites
    assert resolution_by_prerequisite[
        StealthCommandExecutionPrerequisite.APPROVAL_SNAPSHOT.value
    ]["lookup_status"] == StealthCommandExecutionPrerequisiteLookupStatus.MISSING.value
    assert resolution_by_prerequisite[
        StealthCommandExecutionPrerequisite.APPROVAL_SNAPSHOT.value
    ]["lookup_ran"] is True
    assert resolution_by_prerequisite[command_specific_prerequisite][
        "lookup_status"
    ] == StealthCommandExecutionPrerequisiteLookupStatus.BLOCKED_BY_DEPENDENCY.value
    assert resolution_by_prerequisite[command_specific_prerequisite][
        "missing_reason"
    ] == "admission_prerequisites_missing"
    assert resolution_by_prerequisite[
        StealthCommandExecutionPrerequisite.MANAGER_INVOCATION_POLICY.value
    ]["lookup_status"] == (
        StealthCommandExecutionPrerequisiteLookupStatus.BLOCKED_BY_DEPENDENCY.value
    )
    assert resolution_by_prerequisite[
        StealthCommandExecutionPrerequisite.MANAGER_INVOCATION_POLICY.value
    ]["missing_reason"] == "admission_prerequisites_missing"
    for policy_prerequisite in (
        StealthCommandExecutionPrerequisite.COINBASE_EXCHANGE_SUBMISSION_POLICY.value,
        StealthCommandExecutionPrerequisite.POST_WRITE_RECONCILIATION_EXECUTION_POLICY.value,
        StealthCommandExecutionPrerequisite.STATE_MUTATION_POLICY.value,
    ):
        assert resolution_by_prerequisite[policy_prerequisite]["lookup_status"] == (
            StealthCommandExecutionPrerequisiteLookupStatus.BLOCKED_BY_DEPENDENCY.value
        )
        assert resolution_by_prerequisite[policy_prerequisite]["missing_reason"] == (
            "admission_prerequisites_missing"
        )
    service_resolution = resolution_by_prerequisite[
        StealthCommandExecutionPrerequisite.LIVE_EXECUTION_SERVICE.value
    ]
    if (
        StealthCommandExecutionPrerequisite.LIVE_EXECUTION_SERVICE.value
        in resolved_prerequisites
    ):
        assert service_resolution["lookup_status"] == (
            StealthCommandExecutionPrerequisiteLookupStatus.RESOLVED.value
        )
        assert service_resolution["resolved"] is True
        assert service_resolution["source"] == M55_STEALTH_REVEAL_DRY_RUN_SERVICE_SOURCE
        assert service_resolution["missing_reason"] is None
    else:
        assert service_resolution["lookup_status"] == (
            StealthCommandExecutionPrerequisiteLookupStatus.DISABLED.value
        )
        assert service_resolution["source"] == DISABLED_LIVE_EXECUTION_SERVICE_SOURCE
    adapter_resolution = resolution_by_prerequisite[
        StealthCommandExecutionPrerequisite.LIVE_EXECUTION_ADAPTER.value
    ]
    if (
        StealthCommandExecutionPrerequisite.LIVE_EXECUTION_ADAPTER.value
        in resolved_prerequisites
    ):
        assert adapter_resolution["lookup_status"] == (
            StealthCommandExecutionPrerequisiteLookupStatus.RESOLVED.value
        )
        assert adapter_resolution["resolved"] is True
        assert adapter_resolution["source"] == "m55_stealth_reveal_backend_dry_run"
        assert adapter_resolution["missing_reason"] is None
    else:
        assert adapter_resolution["source"] == (
            DISABLED_STEALTH_LIVE_EXECUTION_ADAPTER_SOURCE
        )
    assert resolution_by_prerequisite[
        StealthCommandExecutionPrerequisite.POST_WRITE_RECONCILIATION.value
    ]["source"] == "admin_api_stealth_post_write_reconciliation_proof_log"
    assert resolution_by_prerequisite[
        StealthCommandExecutionPrerequisite.POST_WRITE_RECONCILIATION.value
    ]["lookup_status"] == StealthCommandExecutionPrerequisiteLookupStatus.MISSING.value
    assert resolution_by_prerequisite[
        StealthCommandExecutionPrerequisite.POST_WRITE_RECONCILIATION.value
    ]["missing_reason"] == "no_matching_post_write_reconciliation_proof"
    stages = contract["execution_readiness_stages"]
    assert contract["execution_readiness_stage_count"] == len(required_prerequisites)
    assert contract["blocked_execution_readiness_stage_count"] == len(
        missing_prerequisites
    )
    assert contract["passed_execution_readiness_stage_count"] == len(
        resolved_prerequisites
    )
    assert [stage["stage_order"] for stage in stages] == list(
        range(1, len(stages) + 1)
    )
    stage_by_prerequisite = {stage["prerequisite"]: stage for stage in stages}
    assert set(stage_by_prerequisite) == required_prerequisites
    expected_workflow_family = _expected_stealth_workflow_family(mutation_family)
    for stage in stages:
        resolver_row = resolution_by_prerequisite[stage["prerequisite"]]
        assert stage["workflow_family"] == expected_workflow_family
        assert stage["mutation_family"] == mutation_family
        assert stage["source"] == resolver_row["source"]
        assert stage["route"] == resolver_row["route"]
        assert stage["method"] == resolver_row["method"]
        assert stage["identity_key"] == "stealth_order_id"
        assert stage["identity_value"] == identity_value
        assert stage["lookup_status"] == resolver_row["lookup_status"]
        assert stage["required"] is True
        if stage["prerequisite"] in resolved_prerequisites:
            assert stage["status"] == AdminApiGateStatus.PASSED.value
            assert stage["resolved"] is True
            assert stage["blocking"] is False
        else:
            assert stage["status"] == AdminApiGateStatus.BLOCKED.value
            assert stage["resolved"] is False
            assert stage["blocking"] is True
        assert stage["missing_reason"] == resolver_row["missing_reason"]
        assert stage["next_required_contract"]
        assert stage["backend_owned"] is True
        assert stage["route_bound"] is True
        assert stage["command_context_bound"] is True
        assert stage["browser_authority"] == "display_only"
        assert stage["bff_authority"] == "forward_only_no_execution"
        assert stage["no_live_execution"] is True
        assert stage["manager_invocation_allowed"] is False
        assert stage["coinbase_read_allowed"] is False
        assert stage["coinbase_write_allowed"] is False
        assert stage["state_mutation_allowed"] is False
        assert stage["detail"]
    _assert_stealth_command_specific_proof_contracts(
        contract,
        mutation_family=mutation_family,
    )
    if (
        StealthCommandExecutionPrerequisite.LIVE_EXECUTION_SERVICE.value
        in resolved_prerequisites
    ):
        assert contract["live_execution_service_source"] == (
            M55_STEALTH_REVEAL_DRY_RUN_SERVICE_SOURCE
        )
        assert contract["live_execution_service_missing_reason"] is None
    else:
        assert contract["live_execution_service_source"] == (
            DISABLED_LIVE_EXECUTION_SERVICE_SOURCE
        )
        assert contract["live_execution_service_missing_reason"] == (
            "live_execution_disabled"
        )
    _assert_stealth_live_execution_service_contract(
        contract["live_execution_service_contract"],
        route=route,
        module_id=module_id,
        service_method=service_method,
        action_class=payload["action_class"],
        configured=(
            StealthCommandExecutionPrerequisite.LIVE_EXECUTION_SERVICE.value
            in resolved_prerequisites
        ),
    )
    _assert_disabled_live_execution_intent(
        contract["live_execution_intent_contract"],
        route=route,
        method="POST",
        module_id=module_id,
        service_method=service_method,
        identity_key="stealth_order_id",
        identity_value=identity_value,
    )
    if (
        StealthCommandExecutionPrerequisite.CANCEL_REPLACE_PROOF.value
        in required_prerequisites
    ):
        _assert_active_placement_cancel_replace_contract(
            contract["active_placement_cancel_replace_contract"],
            mutation_family=mutation_family,
            route=route,
        )
    else:
        assert contract["active_placement_cancel_replace_contract"] is None
    if (
        StealthCommandExecutionPrerequisite.LIVE_EXECUTION_ADAPTER.value
        in resolved_prerequisites
    ):
        assert contract["live_execution_adapter_source"] == (
            "m55_stealth_reveal_backend_dry_run"
        )
        assert contract["live_execution_adapter_status"] == "approval_required"
        assert contract["live_execution_adapter_missing_reason"] is None
    else:
        assert contract["live_execution_adapter_source"] == (
            DISABLED_STEALTH_LIVE_EXECUTION_ADAPTER_SOURCE
        )
        assert contract["live_execution_adapter_status"] == "live_disabled"
        assert contract["live_execution_adapter_missing_reason"] == (
            "live_execution_adapter_disabled"
        )
    if (
        StealthCommandExecutionPrerequisite.ACTIVE_PLACEMENT_EXCHANGE_TRUTH.value
        in required_prerequisites
    ):
        _assert_active_placement_exchange_truth_contract(
            contract["active_placement_exchange_truth_contract"],
            mutation_family=mutation_family,
            route=route,
        )
    else:
        assert contract["active_placement_exchange_truth_contract"] is None
    _assert_stealth_live_execution_adapter_contract(
        contract["live_execution_adapter_contract"],
        route=route,
        module_id=module_id,
        service_method=service_method,
        action_class=payload["action_class"],
        configured=(
            StealthCommandExecutionPrerequisite.LIVE_EXECUTION_ADAPTER.value
            in resolved_prerequisites
        ),
    )
    assert contract["post_write_reconciliation_route"] == (
        POST_WRITE_RECONCILIATION_ROUTE
    )
    assert contract["post_write_reconciliation_method"] == (
        POST_WRITE_RECONCILIATION_METHOD
    )
    assert contract["post_write_reconciliation_source"] == (
        POST_WRITE_RECONCILIATION_SOURCE
    )
    assert contract["post_write_reconciliation_missing_reason"] == (
        "post_write_reconciliation_missing"
    )
    _assert_stealth_post_write_reconciliation_boundary(
        contract["post_write_reconciliation_boundary"],
        mutation_family=mutation_family,
        route=route,
        service_method=service_method,
        identity_value=identity_value,
        exact_context_present=True,
    )
    assert contract["canonical_execution_path"] == contract["manager_methods"]
    _assert_stealth_execution_candidate(
        contract,
        mutation_family=mutation_family,
        route=route,
        service_method=service_method,
        identity_value=identity_value,
        manager_methods=contract["manager_methods"],
        exact_command_context_present=True,
    )
