        action_class=AdminApiActionClass.LOCAL_STATE_MUTATION,
        required_permission=AdminApiPermission.STEALTH_RECONCILIATION_EXECUTE,
        approval_snapshot_id="stealth-reconciliation-approval-unsafe-001",
